"""Build human-review queues for Horizon evidence validation; never infer validation."""
from pathlib import Path
import csv
R=Path(__file__).resolve().parent

def read(name):
    with (R/name).open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def write(name, fields, rows):
    with (R/name).open('w',encoding='utf-8-sig',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
ledger=read('SOURCE_TRACEABILITY_LEDGER_V25_6.csv')
cross=read('MATRIX_TRACEABILITY_CROSSWALK_V25_6.csv')
source_fields=['Source Row ID','Major','Claim Number','Claim Type','Institution','Source Title','URL','Source Type','Original Claim Status','Original Scope / Limitation',
'Reviewer','Review Date (YYYY-MM-DD)','Page/Section Reviewed','Exact Supporting Passage or Precise Paraphrase','Claim Supported? (YES/NO/PARTIAL/UNCLEAR)','Evidence Scope Confirmed? (YES/NO)','Contradiction or Limitation Found','Review Decision (UNREVIEWED/ACCEPTED/REJECTED/NEEDS FOLLOW-UP)','Reviewer Notes']
sources=[]
for r in ledger:
    sources.append({'Source Row ID':r['Source Row ID'],'Major':r['Major'],'Claim Number':r['Original Claim Number'],'Claim Type':r['Claim Type'],'Institution':r['Institution'],'Source Title':r['Source Title'],'URL':r['URL'],'Source Type':r['Source Type'],'Original Claim Status':r['Claim Status (Original)'],'Original Scope / Limitation':r['Original Scope / Limitation'],'Reviewer':'','Review Date (YYYY-MM-DD)':'','Page/Section Reviewed':'','Exact Supporting Passage or Precise Paraphrase':'','Claim Supported? (YES/NO/PARTIAL/UNCLEAR)':'','Evidence Scope Confirmed? (YES/NO)':'','Contradiction or Limitation Found':'','Review Decision (UNREVIEWED/ACCEPTED/REJECTED/NEEDS FOLLOW-UP)':'UNREVIEWED','Reviewer Notes':''})
write('SOURCE_PAGE_REVIEW_QUEUE_V25_7.csv',source_fields,sources)
matrix_fields=['Matrix Pair ID','Major','Subject ID','EMASI Subject','Current Guidance Role','Original Matrix Claim ID','Original Audit Status','Proposed Source Row IDs (human-confirmed only)','EMASI Grade Level','EMASI Official Document / Version','EMASI Learning Outcome / Section','Exact EMASI Evidence or Precise Paraphrase','University Source Row IDs Reviewed','Relationship Supported? (YES/NO/PARTIAL/UNCLEAR)','Guidance Decision (KEEP EXPLORATORY/REVISE/REMOVE/ELIGIBLE FOR FURTHER REVIEW)','Reviewer','Review Date (YYYY-MM-DD)','Reviewer Notes']
mat=[]
for r in cross:
    mat.append({'Matrix Pair ID':r['Matrix Pair ID'],'Major':r['Major'],'Subject ID':r['Subject ID'],'EMASI Subject':r['EMASI Subject'],'Current Guidance Role':r['Current Guidance Role'],'Original Matrix Claim ID':r['Matrix Claim ID (Original)'],'Original Audit Status':r['Audit Status (Original)'],'Proposed Source Row IDs (human-confirmed only)':'','EMASI Grade Level':'','EMASI Official Document / Version':'','EMASI Learning Outcome / Section':'','Exact EMASI Evidence or Precise Paraphrase':'','University Source Row IDs Reviewed':'','Relationship Supported? (YES/NO/PARTIAL/UNCLEAR)':'','Guidance Decision (KEEP EXPLORATORY/REVISE/REMOVE/ELIGIBLE FOR FURTHER REVIEW)':'KEEP EXPLORATORY','Reviewer':'','Review Date (YYYY-MM-DD)':'','Reviewer Notes':''})
write('MATRIX_PAIR_REVIEW_QUEUE_V25_7.csv',matrix_fields,mat)
protocol='''# Horizon v25.7 — Human Evidence Review Protocol\n\n## Purpose\nProvide a repeatable, auditable workflow for reviewing source-page claims and then checking exploratory major–subject guidance against actual EMASI curriculum evidence. This release creates blank review queues; it does not perform or imply human review.\n\n## Files\n- `SOURCE_PAGE_REVIEW_QUEUE_V25_7.csv`: one row per source-register record (186 rows).\n- `MATRIX_PAIR_REVIEW_QUEUE_V25_7.csv`: one row per major–subject pair (260 rows).\n\n## Stage A — review the cited source page\nFor each source row, open the exact URL and record the page/section and the smallest passage or precise paraphrase that supports (or fails to support) the original claim. Record whether the claim is supported, partially supported, unclear, or contradicted. Distinguish programme availability, curriculum content, disciplinary context, professional guidance, prerequisites, and school-subject alignment. Do not treat a university course appearing in a degree plan as proof that a high-school subject is required.\n\nA row may be marked `ACCEPTED` only when reviewer, review date, page/section, evidence excerpt/paraphrase, claim-support decision, and scope confirmation are completed. `ACCEPTED` means only that the stated source claim was checked within its stated scope; it does not mean EMASI alignment is proven.\n\n## Stage B — review a major–subject pair\nUse the second queue only after reviewing relevant university sources and obtaining the actual EMASI grade-level syllabus or learning outcomes. Record exact EMASI document/version, grade, section/outcome, and supporting text. Link source rows only after a reviewer has checked that each cited page supports the relevant part of the relationship.\n\n`ELIGIBLE FOR FURTHER REVIEW` is not a verified status. It means the reviewer believes the evidence is sufficiently complete to submit to a separate academic/content approval step. Do not publish `verified` based solely on university programme listings, source URL reachability, reference counts, or inferred Claim IDs.\n\n## Decision rules\n- `KEEP EXPLORATORY`: evidence is incomplete or only contextual.\n- `REVISE`: evidence supports a narrower or different statement.\n- `REMOVE`: the source contradicts or does not support the guidance.\n- `ELIGIBLE FOR FURTHER REVIEW`: both sides of the relationship have traceable, reviewed evidence; independent approval is still required.\n\n## Current boundary\nNo source-page review or EMASI syllabus comparison is completed by this package. The CSV fields are intentionally blank, and the existing guidance remains exploratory.\n'''
(R/'HUMAN_EVIDENCE_REVIEW_PROTOCOL_V25_7.md').write_text(protocol,encoding='utf-8')
(R/'V25_7_CHANGELOG.md').write_text('''# v25.7 changelog\n\n- Added a 186-row source-page review queue with fields for reviewer, page section, supporting passage, claim support, scope, and decision.\n- Added a 260-row major–subject pair review queue with explicit EMASI syllabus and learning-outcome evidence fields.\n- Added a staged human-review protocol with conservative decision rules.\n- Review fields remain blank/unreviewed; no claim or subject relationship is promoted.\n- App logic, protected v24 baseline, and Railway deployment remain unchanged.\n''',encoding='utf-8')
(R/'README_V25_7.md').write_text('''# Horizon v25.7 — Human Evidence Review Workflow\n\nThis is a documentation/workflow increment, not a content verification release.\n\nNew files:\n- `SOURCE_PAGE_REVIEW_QUEUE_V25_7.csv` (186 source rows)\n- `MATRIX_PAIR_REVIEW_QUEUE_V25_7.csv` (260 major–subject pairs)\n- `HUMAN_EVIDENCE_REVIEW_PROTOCOL_V25_7.md`\n- `build_review_workflow_v25_7.py`\n- `qa_v25_7.py`\n\nRegenerate and check: `python build_review_workflow_v25_7.py && python qa_v25_7.py`\n\nNo live URL checks, page-content review, EMASI syllabus validation, browser test, privacy review, or deployment are claimed.\n''',encoding='utf-8')
(R/'VERSION.txt').write_text('Horizon v25.7 — Human Evidence Review Workflow\n',encoding='utf-8')
print(f'Generated {len(sources)} source review rows and {len(mat)} matrix review rows')
